SELECT tg.team_id, COUNT(DISTINCT tg.game_id) AS scheduled_games FROM ( SELECT g.id AS game_id, g.home_team_id AS team_id FROM bs_game g JOIN bs_event e ON g.event_id = e.id WHERE 1 = 1
UNION ALL SELECT g.id AS game_id, g.away_team_id AS team_id FROM bs_game g JOIN bs_event e ON g.event_id = e.id WHERE 1 = 1
) tg GROUP BY tg.team_id

