mapper.sql:
SELECT s.player_id AS playerId, COALESCE(NULLIF(TRIM(p.name), ''), p.short_name) AS playerName, p.team_id AS teamId, t.name AS teamName, (CASE WHEN p.positions IS NOT NULL AND p.positions != '' AND p.positions != '[]' THEN TRIM(REPLACE(REPLACE(REPLACE(SUBSTR(p.positions, 2, LENGTH(p.positions)-2), '"', ''), '[', ''), ']', '')) ELSE NULL END) AS position, p.number AS number, COUNT(DISTINCT s.game_id) AS gp, COALESCE(SUM(s.gs), 0) AS gs, COALESCE(SUM(s.svo), 0) AS svo, COALESCE(SUM(s.cg), 0) AS cg, COALESCE(SUM(s.pg), 0) AS pg, COALESCE(SUM(s.w), 0) AS w, COALESCE(SUM(s.l), 0) AS l, COALESCE(SUM(s.sv), 0) AS sv, COALESCE(SUM(s.hld), 0) AS hld, (CASE WHEN COALESCE(SUM(), 0) <= 0 THEN 0 ELSE FLOOR(COALESCE(SUM(), 0) / 3.0) + (COALESCE(SUM(), 0) - 3 * FLOOR(COALESCE(SUM(), 0) / 3.0)) / 10.0 END) AS ip, CASE WHEN COALESCE(SUM(), 0) > 0 THEN ROUND(CAST( (COALESCE(SUM(), 0) + COALESCE(SUM(s.pitch_bb_hp), 0)) * 3.0 / NULLIF(COALESCE(SUM(), 0), 0) AS numeric), 2) ELSE NULL END AS whip, CASE WHEN COALESCE(SUM(), 0) > 0 THEN ROUND(CAST(27.0 * COALESCE(SUM(s.er), 0) / NULLIF(COALESCE(SUM(), 0), 0) AS numeric), 2) ELSE NULL END AS era, COALESCE(SUM(s.pitch_pa), 0) AS pitchPa, COALESCE(SUM(s.pitch_bf), 0) AS pitchBf, COALESCE(SUM(s.np), 0) AS np, COALESCE(SUM(), 0) AS pitchH, COALESCE(SUM(s.pitch_hr), 0) AS pitchHr, COALESCE(SUM(s.pitch_inside_park_hr), 0) AS pitch_inside_park_hr, CASE WHEN COALESCE(SUM(s.pitch_bb), 0) + COALESCE(SUM(s.pitch_hbp), 0) > 0 THEN COALESCE(SUM(s.pitch_bb), 0) ELSE GREATEST(COALESCE(SUM(s.pitch_bb_hp), 0) - COALESCE(SUM(s.pitch_hbp), 0), 0) END AS pitchBb, COALESCE(SUM(s.pitch_ibb), 0) AS pitchIbb, COALESCE(SUM(s.pitch_hbp), 0) AS pitchHbp, COALESCE(SUM(s.pitch_so), 0) AS pitchSo, COALESCE(SUM(s.wp), 0) AS wp, COALESCE(SUM(s.bk), 0) AS bk, COALESCE(SUM(), 0) AS pitchR, COALESCE(SUM(s.er), 0) AS er, COALESCE(SUM(s.go), 0) AS go, COALESCE(SUM(s.fo), 0) AS fo, CASE WHEN COALESCE(SUM(s.fo), 0) > 0 THEN ROUND(CAST(1.0 * SUM(s.go) / SUM(s.fo) AS numeric), 2) ELSE NULL END AS goFo FROM bs_game_player_stat s JOIN bs_game g ON s.game_id = g.id JOIN bs_event e ON g.event_id = e.id JOIN bs_player p ON s.player_id = p.id AND p.deleted_at IS NULL LEFT JOIN bs_team t ON p.team_id = t.id LEFT JOIN (
) tsg ON tsg.team_id = p.team_id WHERE s.is_pitcher = 1 AND s.ip IS NOT NULL AND s.ip > 0
GROUP BY s.player_id, p.name, p.short_name, p.team_id, p.positions, p.number, t.name

